import {compileRelation} from './algebra.js?v=13';
export function planeFunctionPanel({container,language,onChange}){
 const panel=document.createElement('section');panel.className='function-panel';panel.hidden=true;panel.ariaLabel='Cartesian functions';container.append(panel);let plane=null,closed=null,signature='',draft='',cursor=0,editing=null,tab='123';const tr=(a,b)=>language()==='bm'?b:a;
 const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
 function change(fn){if(plane.locked)return;onChange(plane.id,fn);}
 function paint(){const d=panel.querySelector('.function-display');d.replaceChildren(document.createTextNode(draft.slice(0,cursor)),el('span','│','function-caret'),document.createTextNode(draft.slice(cursor)));d.setAttribute('aria-valuetext',draft);panel.querySelector('.function-error').textContent='';}
 function key(k){if(k==='Enter'){submit();return;}if(k==='C'){draft='';cursor=0;}else if(k==='⌫'){if(cursor){draft=draft.slice(0,cursor-1)+draft.slice(cursor);cursor--;}}else if(k==='←')cursor=Math.max(0,cursor-1);else if(k==='→')cursor=Math.min(draft.length,cursor+1);else{const templates={'x²':'^2','xʸ':'^()','√':'sqrt()','|x|':'abs()','a/b':'()/()'};const value=templates[k]??(k==='sin'||k==='cos'||k==='tan'||k==='ln'||k==='log'||k==='exp'?k+'()':k);if(draft.length+value.length>250)return;draft=draft.slice(0,cursor)+value+draft.slice(cursor);cursor+=value.length;if(value==='()/()')cursor-=4;else if(value.endsWith('()'))cursor--;}
 paint();panel.querySelector('.function-display').focus({preventScroll:true});}
 function submit(){try{compileRelation(draft);}catch{panel.querySelector('.function-error').textContent=tr('Check the expression, e.g. y = x² or y ≤ 2x + 1.','Semak ungkapan, contoh y = x² atau y ≤ 2x + 1.');return;}if(plane.locked){panel.querySelector('.function-error').textContent=tr('Unlock this plane to edit its functions.','Buka kunci satah untuk menyunting fungsi.');return;}if(!editing&&(plane.functions?.length??0)>=12){panel.querySelector('.function-error').textContent=tr('Maximum 12 functions per plane.','Maksimum 12 fungsi setiap satah.');return;}const source=draft,id=editing;editing=null;draft='';cursor=0;change(o=>{o.functions??=[];const f=o.functions.find(f=>f.id===id);if(f)f.source=source;else o.functions.push({id:crypto.randomUUID(),source,visible:true,colour:['#397ce9','#e96562','#23a678','#ac70dd'][o.functions.length%4]});});render();}
 function button(name,fn){const b=el('button',name);b.type='button';b.onpointerdown=e=>e.preventDefault();b.onclick=fn;return b;}
 function render(){if(!plane)return;panel.replaceChildren();const head=el('div',undefined,'function-heading');head.append(el('strong',tr('Functions','Fungsi')),button('×',()=>{closed=plane.id;panel.hidden=true;}));head.lastChild.ariaLabel=tr('Close functions','Tutup fungsi');panel.append(head,el('p',tr('Use x and y · Trigonometry in radians','Gunakan x dan y · Trigonometri dalam radian')));
 const list=el('div',undefined,'function-list');for(const f of plane.functions??[]){const row=el('div'),show=button(f.visible===false?'○':'●',()=>change(o=>{const item=o.functions.find(v=>v.id===f.id);item.visible=item.visible===false;}));show.ariaLabel=tr('Toggle ','Togol ')+f.source;show.style.color=f.colour;show.setAttribute('aria-pressed',String(f.visible!==false));const edit=button(f.source,()=>{editing=f.id;draft=f.source;cursor=draft.length;render();}),remove=button('×',()=>change(o=>o.functions=o.functions.filter(v=>v.id!==f.id)));remove.ariaLabel=tr('Remove ','Buang ')+f.source;row.append(show,edit,remove);list.append(row);}panel.append(list);
 const display=el('div',undefined,'function-display');display.tabIndex=0;display.setAttribute('role','textbox');display.setAttribute('aria-readonly','true');display.ariaLabel=tr('Function expression','Ungkapan fungsi');panel.append(display);const error=el('p','', 'function-error');error.setAttribute('role','status');panel.append(error);const tabs=el('div',undefined,'function-tabs');for(const t of ['123','f(x)','ABC','#&¬']){const b=button(t,()=>{tab=t;render();});b.setAttribute('aria-pressed',String(t===tab));tabs.append(b);}panel.append(tabs);
 const keys=el('div',undefined,'function-keys'),symbols=tab==='123'?['x','y','π','e','x²','xʸ','√','|x|','<','>','≤','≥','a/b',',','(',')']:tab==='f(x)'?['sin','cos','tan','ln','log','exp','√','|x|','x²','xʸ','π','e']:tab==='ABC'?['x','y']:['<','>','≤','≥','=','(',')',','];const maths=el('div'),numbers=el('div');for(const k of symbols)maths.append(button(k,()=>key(k)));for(const k of ['7','8','9','×','÷','4','5','6','+','−','1','2','3','=','⌫','C','0','.','←','→'])numbers.append(button(k,()=>key(k)));keys.append(maths,numbers);panel.append(keys,button(tr(editing?'Update graph':'Plot',editing?'Kemaskini graf':'Lukis graf'),submit));panel.lastChild.className='function-submit';paint();}
 panel.onkeydown=e=>{e.stopPropagation();if(e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='Escape'){panel.hidden=true;closed=plane?.id;return;}if(e.key==='Enter'&&e.target.tagName==='BUTTON')return;const k={Backspace:'⌫',Delete:'⌫',ArrowLeft:'←',ArrowRight:'→',Enter:'Enter'}[e.key]??(/^[0-9xyπe.+*/^()=<>\-]$/.test(e.key)?e.key:null);if(k){e.preventDefault();key(k);}};
 return {show(){closed=null;panel.hidden=!plane;},sync(o,rect){if(!o){plane=null;panel.hidden=true;return;}if(plane?.id!==o.id){closed=null;draft='';cursor=0;editing=null;signature='';}plane=o;const next=JSON.stringify([o.id,o.functions,language()]);if(signature!==next){signature=next;render();}panel.hidden=closed===o.id;if(rect&&!panel.hidden){const w=panel.offsetWidth,h=panel.offsetHeight,W=container.clientWidth,H=container.clientHeight;const x=rect.right+w+12<W?rect.right+12:rect.left-w-12>=80?rect.left-w-12:Math.max(80,W-w-12);panel.style.left=Math.max(4,Math.min(W-w-4,x))+'px';panel.style.top=Math.max(76,Math.min(H-h-8,rect.top))+'px';}}};
}
